"""Dependency-free static publication. Run from repository root."""
import json, html, re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'public'
BASE='https://trailwise-gear.jaydenisraelruiz.workers.dev'
DATE='2026-10-26'
guides=json.loads((ROOT/'content/guides.json').read_text())
e=html.escape
def write(path,text):
    p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text)
def page(path,title,description,body,schema=None):
    url=BASE+('/' if path=='index.html' else '/'+path.replace('index.html',''))
    data={'@context':'https://schema.org','@type':'Organization','name':'Trailwise Gear','url':BASE} if schema is None else schema
    write(path,f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="1MeKjoKHpi5pSPYf6qovnzJHeW9wuBDJeyeqPOC2RTk"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Trailwise Gear</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta name="theme-color" content="#183f35"><link rel="stylesheet" href="/style.css"><link rel="icon" href="/icon.svg" type="image/svg+xml"><script type="application/ld+json">{json.dumps(data)}</script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/" aria-label="Trailwise Gear home"><span class="mark" aria-hidden="true">△</span> TRAILWISE <span>GEAR</span></a><nav aria-label="Main navigation"><a href="/guides/">All guides</a><a href="/comparisons/">Compare gear</a><a href="/about/">About</a></nav></header><main id="main">{body}</main><footer><div><a class="brand" href="/">TRAILWISE GEAR</a><p>Go farther. Spend smarter.</p><p>Independent research. Practical tradeoffs. No invented tests.</p></div><nav aria-label="Publication policies"><a href="/contact/">Contact & corrections</a><a href="/editorial-policy/">Editorial policy</a><a href="/affiliate-disclosure/">Affiliate disclosure</a><a href="/privacy/">Privacy</a><a href="/sitemap.xml">Sitemap</a></nav><p class="fine">© 2026 Trailwise Gear. No affiliate links are currently used. Conditions and equipment change; check current instructions before a trip.</p></footer></body></html>''')
def card(g):
    return f'<article class="card"><p class="eyebrow">{e(g["category"])}</p><h3><a href="/guides/{g["slug"]}/">{e(g["title"])}</a></h3><p>{e(g["description"])}</p><span class="fine">Research-based guide · Read guide →</span></article>'
def cards(items):return '<div class="grid">'+''.join(card(g) for g in items)+'</div>'
page('index.html','Practical gear advice for affordable adventures','Budget-first camping and trail guides. Clear comparisons, useful checklists, and honest research without invented product testing.',f'''<section class="hero"><div><p class="eyebrow">LESS HYPE. MORE OUTSIDE.</p><h1>Good adventures.<br>Smarter gear choices.</h1><p class="lede">Spend on what helps. Skip what doesn't. Practical guides for your first campsite, next trail day, and everything you carry along.</p><a class="button" href="/guides/first-car-camping-trip/">Plan your first camping trip <span aria-hidden="true">↗</span></a><a class="text-link" href="/comparisons/">Compare before you buy →</a></div><div class="landscape" aria-hidden="true"><span class="sun"></span><span class="ridge back"></span><span class="ridge front"></span><span class="trail"></span><span class="caption">THE OUTSIDE IS FOR EVERYONE.</span></div></section><div class="trust"><span>Budget comes first</span><span>Sources you can check</span><span>Research clearly labeled</span></div><section id="guides"><div class="section-head"><div><p class="eyebrow">YOUR STARTING POINT</p><h2>Buy less. Know more.</h2></div><a href="/guides/">Explore all 10 guides →</a></div>{cards(guides[:3])}</section><section class="feature"><p class="eyebrow">THE COMPLETE KIT MATTERS</p><h2>A cheap burner isn't always a cheap kitchen.</h2><p>Compare the pot, fuel, accessories, and meals—not just the price on the box.</p><a class="button light" href="/guides/pocketrocket-2-vs-jetboil-flash/">PocketRocket 2 vs Jetboil Flash →</a></section><section><div class="section-head"><div><p class="eyebrow">VEHICLE & TRAIL</p><h2>Prepare before you upgrade.</h2></div></div>{cards(guides[-3:])}</section><section class="about-strip"><h2>Advice with the limits left in.</h2><p>We explain what the evidence supports, where the tradeoffs are, and when you may not need to buy anything at all. These initial guides are desk-researched, with no claim of hands-on testing.</p><a href="/editorial-policy/">How our guides are made →</a></section>''')
page('guides/index.html','Camping and trail guides','Browse practical camping, cooking, vehicle, and gear-buying guides.','<div class="page-intro"><p class="eyebrow">THE GUIDEBOOK</p><h1>A little planning goes a long way.</h1><p>Choose a real problem to solve, then find the equipment that fits.</p></div>'+cards(guides))
page('comparisons/index.html','Research-based gear comparisons','Compare complete systems and practical tradeoffs before buying outdoor gear.','<div class="page-intro"><p class="eyebrow">BEFORE YOU BUY</p><h1>Compare the tradeoffs.</h1><p>Research-based comparisons. No lab scores, purchased rankings, or claims of personal testing.</p></div>'+cards([g for g in guides if g['category']=='Gear comparisons']))
for g in guides:
    toc='<nav class="toc" aria-label="In this guide"><strong>In this guide</strong><ol>'+''.join(f'<li><a href="#section-{i}">{e(s[0])}</a></li>' for i,s in enumerate(g['sections']))+'</ol></nav>'
    body=f'<div class="article-head"><a href="/guides/">← All guides</a><p class="eyebrow">{e(g["category"])}</p><h1>{e(g["title"])}</h1><p class="lede">{e(g["description"])}</p><p class="fine">By Trailwise Gear editorial desk · Published and source-checked October 26, 2026 · Desk research</p></div><div class="article-layout">{toc}<article class="prose"><aside class="answer"><strong>The practical answer</strong><p>{e(g["answer"])}</p></aside>'
    for i,(heading,text) in enumerate(g['sections']):
        body+=f'<section id="section-{i}"><h2>{e(heading)}</h2>'+''.join(f'<p>{e(p)}</p>' for p in text.split('\n'))+'</section>'
    body+='<section class="sources"><h2>Sources & evidence</h2><p>Manufacturer specifications and source guidance were checked on October 26, 2026. Buying recommendations are our editorial judgments. We have not tested these products.</p><ul>'+''.join(f'<li><a href="{e(url)}" rel="external">{e(label)}</a></li>' for label,url in g['sources'])+'</ul><p>No affiliate tracking is used. <a href="/contact/">Report a correction</a>.</p></section></article></div><section><h2>Keep planning</h2>'+cards([next(x for x in guides if x['slug']==slug) for slug in g['related']])+'</section>'
    schema={'@context':'https://schema.org','@type':'Article','headline':g['title'],'description':g['description'],'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'Trailwise Gear editorial desk'},'publisher':{'@type':'Organization','name':'Trailwise Gear'},'mainEntityOfPage':BASE+'/guides/'+g['slug']+'/','citation':[s[1] for s in g['sources']]}
    page('guides/'+g['slug']+'/index.html',g['title'],g['description'],body,schema)
policies={
'about':('About Trailwise Gear','Practical outdoor information for people who care where their money goes.', [('Our purpose','Trailwise Gear is an independent publication operated by Jayden Ruiz. We help budget-conscious campers and outdoor enthusiasts compare equipment, prepare for trips, and avoid buying gear that does not solve a real problem.'),('What you will find','Our initial publication focuses on beginner car camping, complete cooking systems, and conservative vehicle-trip preparation. The first ten guides are desk-researched. They do not represent field tests or professional assessments of your equipment.'),('How the business works','We intend to earn revenue through disclosed affiliate relationships after approval. There are currently no monetized links. Editorial recommendations include borrowing, reusing equipment, and delaying purchases when those options fit the reader better.'),('Accountability','Sources and evidence limits appear in each guide. Readers can report factual errors through our contact page. See the editorial policy for our research, AI assistance, and correction practices.')]),
'contact':('Contact & corrections','Send a question or report a factual error.', [('Public contact method','Use the public GitHub issue tracker linked below for editorial questions, broken links, and corrections. A GitHub account is required. This is a public channel: do not include an address, phone number, payment information, account credentials, or other private details.'),('What to include','Include the article URL, the claim or link in question, and a reliable source when possible. For a gear question, include the model and the use case without personal information. We review reports when operating the publication; no response time is guaranteed.'),('Partnership inquiries','Brands may use the same public channel for non-confidential partnership inquiries. We do not accept payment for undisclosed recommendations or fabricated reviews. Do not send confidential contracts or tax information through an issue.')]),
'editorial-policy':('Editorial & review policy','How we research, label evidence, and correct mistakes.', [('Research-based vs hands-on','Every initial guide is desk-researched. Manufacturer statements are attributed and do not become our measured results. A future hands-on review must identify the product version, conditions, method, and limitations. We will not imply that we used a product when we have not.'),('Sources and recommendations','We prioritize manufacturer documentation for specifications and compatibility, public land managers for access guidance, and authoritative safety sources for safety claims. Prices and availability change; we do not publish invented prices or claim real-time stock. We compare complete systems and distinguish editorial judgment from verified facts.'),('AI assistance','AI tools assist with research, writing, development, and maintenance. This does not constitute hands-on product testing or independent expert certification. We check important factual claims against linked sources and do not invent customer reviews, lab results, credentials, or affiliate relationships.'),('Commercial independence','We plan to use affiliate links only after program approval and receipt of real tracking information. A relationship will be disclosed near relevant links. We do not sell positive conclusions. Borrowing and not buying remain legitimate recommendations. No products were supplied for the initial guides.'),('Corrections and updates','Report errors through the contact page. Material corrections will be recorded in the affected article, with an updated date. Dates change when substantive review occurs, not automatically to imply freshness. Safety instructions and local rules must always be checked again before use.')]),
'affiliate-disclosure':('Affiliate disclosure','Our current monetization status and intended disclosure practice.', [('Current status','As of October 26, 2026, Trailwise Gear has no active affiliate tracking links on this website. Manufacturer and reference links are ordinary links. We have not claimed affiliate approval or commissions.'),('Future affiliate links','If we join an affiliate program, we may earn a commission on qualifying purchases through clearly identified links. We will update this disclosure and place a clear disclosure near recommendations containing those links. We will also follow each program’s required wording and linking rules.'),('Your choices','You are free to use our guides without buying anything. We aim to recommend equipment based on fit, evidence, and total cost. Commercial relationships do not establish that a product was tested or that it is the best option for everyone.')]),
'privacy':('Privacy notice','A plain-language description of this site’s current data practices.', [('Scope and current features','This notice describes the Trailwise Gear static website prepared on October 26, 2026. The site code includes no analytics scripts, advertising pixels, newsletter forms, account system, payment collection, embedded videos, or client-side tracking storage. We do not collect affiliate clicks through a site tracking system at present.'),('Hosting and technical data','The site is served by Cloudflare. Requests necessarily expose technical information such as IP addresses and browser request headers to the hosting provider. Cloudflare may process security, operational, and diagnostic data under its own policies. We have not verified the account’s logging or retention settings, so we do not promise that hosting logs are absent or retained for a particular period.'),('External links and contact','External websites apply their own privacy practices. Our public contact method uses GitHub; information posted in an issue is public and GitHub processes account and usage data under its own policies. Do not post private or sensitive information. We have no private contact form on this website.'),('Changes and questions','If we add analytics, forms, advertising, or affiliate tracking, we will review and update this notice to describe the actual implementation. Use the contact page for privacy questions without sharing sensitive details publicly.')])}
for slug,(title,desc,sections) in policies.items():
    body=f'<div class="page-intro"><p class="eyebrow">THE PUBLICATION</p><h1>{e(title)}</h1><p>{e(desc)}</p></div><article class="prose policy">'+''.join(f'<section><h2>{e(h)}</h2><p>{e(t)}</p></section>' for h,t in sections)
    if slug=='contact':body+='<p><a class="button" href="https://github.com/JaydenRuiz669/trailwise-gear/issues">Open the public contact tracker →</a></p>'
    if slug=='privacy':body+='<p><a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement</a></p>'
    body+='</article>';page(slug+'/index.html',title,desc,body)
page('404.html','Page not found','Find a camping or trail guide.','<div class="page-intro"><p class="eyebrow">404 · A DIFFERENT TURN</p><h1>This path ends here.</h1><p>The page may have moved. Browse the guidebook to find your next step.</p><a class="button" href="/guides/">Find a guide →</a></div>')
urls=['/','/guides/','/comparisons/']+['/guides/'+g['slug']+'/' for g in guides]+['/'+s+'/' for s in policies]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}{u}</loc><lastmod>{DATE}</lastmod></url>' for u in urls)+'</urlset>')
write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n')
write('icon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#183f35"/><path d="M10 48 29 14 48 48ZM31 48 43 27 56 48" fill="none" stroke="#eedba6" stroke-width="4"/></svg>')
print(f'Built {len(urls)} indexable pages, custom 404, sitemap and robots.txt')
